// --- Reservas (RF-006, RF-007, RF-008; ADR-001, ADR-002) ---
const R = (cantidad, articulo = "A1", almacen = "LPZ") => ({ articulo, almacen, cantidad });

test("RF-008: stockDisponible = stock − reservado, solo del artículo y almacén pedidos", () => {
  const movs = conIngreso();
  assert.equal(stockDisponible(movs, [], "A1", "LPZ"), 10);
  const reservas = reservar(movs, [], R(4));
  assert.equal(stockDisponible(movs, reservas, "A1", "LPZ"), 6);
  assert.equal(stockDisponible(movs, reservas, "A1", "SCZ"), 0);
  assert.equal(stockDisponible(movs, reservas, "B2", "LPZ"), 0);
  const otras = reservar(movs, reservas, R(2, "B2", "SCZ"));
  assert.equal(stockDisponible(movs, otras, "A1", "LPZ"), 6);
});

test("RF-006: reservar baja el disponible pero no el stock", () => {
  const movs = conIngreso();
  const reservas = reservar(movs, [], R(4));
  assert.equal(stock(movs, "A1", "LPZ"), 10);
  assert.equal(stockDisponible(movs, reservas, "A1", "LPZ"), 6);
});

test("RF-006: reservar más que el disponible falla y no cambia la lista; exactamente el disponible se permite", () => {
  const movs = conIngreso();
  const reservas = reservar(movs, [], R(4));
  assert.throws(() => reservar(movs, reservas, R(7)), (e) => e instanceof Error && /Disponible insuficiente/.test(e.message));
  assert.equal(reservas.length, 1);
  assert.equal(stockDisponible(movs, reservar(movs, reservas, R(6)), "A1", "LPZ"), 0);
  assert.throws(() => reservar(movs, [], R(1, "A1", "SCZ")), /Disponible insuficiente/);
});

test("RF-006: varias reservas de la misma combinación se aceptan mientras alcance el disponible", () => {
  const movs = conIngreso();
  const r2 = reservar(movs, reservar(movs, [], R(3)), R(3));
  assert.equal(r2.length, 2);
  assert.equal(stockDisponible(movs, r2, "A1", "LPZ"), 4);
  assert.throws(() => reservar(movs, r2, R(5)), /Disponible insuficiente/);
});

test("RF-006: cantidad que no es entero positivo lanza RangeError", () => {
  const movs = conIngreso();
  for (const cantidad of [0, -1, 1.5, NaN, "2", undefined, null])
    assert.throws(() => reservar(movs, [], R(cantidad)), RangeError);
});

test("RF-006: sin artículo o almacén se rechaza", () => {
  const movs = conIngreso();
  assert.throws(() => reservar(movs, [], R(1, "", "LPZ")), /artículo y almacén/);
  assert.throws(() => reservar(movs, [], R(1, "A1", "")), /artículo y almacén/);
});

test("RF-007: liberar devuelve la cantidad al disponible", () => {
  const movs = conIngreso();
  const reservas = reservar(movs, [], R(6));
  const liberadas = liberar(reservas, R(2));
  assert.equal(stockDisponible(movs, liberadas, "A1", "LPZ"), 6);
  assert.equal(stockDisponible(movs, liberar(liberadas, R(4)), "A1", "LPZ"), 10);
});

test("RF-007: liberar más de lo reservado falla; cantidad inválida lanza RangeError", () => {
  const movs = conIngreso();
  const reservas = reservar(movs, [], R(3));
  assert.throws(() => liberar(reservas, R(4)), /Reserva insuficiente/);
  assert.throws(() => liberar(reservas, R(1, "A1", "SCZ")), /Reserva insuficiente/);
  assert.throws(() => liberar([], R(1)), /Reserva insuficiente/);
  for (const cantidad of [0, -1, 1.5, NaN, "2"]) assert.throws(() => liberar(reservas, R(cantidad)), RangeError);
  assert.throws(() => liberar(reservas, R(1, "", "LPZ")), /artículo y almacén/);
});

test("ADR-001: las reservas no mutan las listas, devuelven resultados congelados y no hay campo stock/reservado", () => {
  const movs = conIngreso();
  const vacia = Object.freeze([]);
  const reservas = reservar(movs, vacia, R(4));
  assert.equal(vacia.length, 0);
  assert.ok(Object.isFrozen(reservas));
  assert.ok(Object.isFrozen(reservas[0]));
  const liberadas = liberar(reservas, R(1));
  assert.equal(reservas.length, 1);
  assert.equal(liberadas.length, 2);
  assert.ok(Object.isFrozen(liberadas));
  for (const registro of liberadas) {
    assert.ok(!("stock" in registro) && !("reservado" in registro));
  }
  assert.ok(!("stock" in movs[0]));
});

test("S2: un egreso directo ignora las reservas (RF-002 intacto) y deja el disponible negativo", () => {
  const movs = conIngreso();
  const reservas = reservar(movs, [], R(8));
  const despues = registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 9 });
  assert.equal(stock(despues, "A1", "LPZ"), 1);
  assert.equal(stockDisponible(despues, reservas, "A1", "LPZ"), -7);
  assert.throws(() => reservar(despues, reservas, R(1)), /Disponible insuficiente/);
  assert.throws(() => registrarMovimiento(despues, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 2 }), /Stock insuficiente/);
});
